CREATE TABLE research_board(id uuid PRIMARY KEY,title text NOT NULL,state jsonb NOT NULL,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE insight_report(id uuid PRIMARY KEY,kind text NOT NULL,title text NOT NULL,question text NOT NULL DEFAULT '',work_ids uuid[] NOT NULL DEFAULT '{}',sources jsonb NOT NULL DEFAULT '[]',sections jsonb NOT NULL DEFAULT '[]',context jsonb NOT NULL DEFAULT '{}',coverage jsonb NOT NULL DEFAULT '{}',provider text NOT NULL DEFAULT 'extractive-local',confirmed boolean NOT NULL DEFAULT false,history jsonb NOT NULL DEFAULT '[]',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE discovery_feedback(id uuid PRIMARY KEY,context_key text NOT NULL,identity_key text NOT NULL,fingerprint text NOT NULL,state text NOT NULL,reason text NOT NULL,defer_until timestamptz,version integer NOT NULL DEFAULT 1,history jsonb NOT NULL DEFAULT '[]',updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(context_key,identity_key));
CREATE TABLE collection_watch_snapshot(collection_id uuid PRIMARY KEY REFERENCES collection(id),snapshot jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE collection_digest(id uuid PRIMARY KEY,collection_id uuid REFERENCES collection(id),kind text NOT NULL,fingerprint text NOT NULL,payload jsonb NOT NULL,seen_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(collection_id,fingerprint));
